Add a real-time WebSocket chat room using the Connection Manager pattern:

```python
from fastapi import WebSocket, WebSocketDisconnect
from fastapi.responses import HTMLResponse

# --- Connection Manager ---
class ConnectionManager:
    def __init__(self):
        self.connections: list[WebSocket] = []

    async def connect(self, ws: WebSocket):
        await ws.accept()
        self.connections.append(ws)

    def disconnect(self, ws: WebSocket):
        self.connections.remove(ws)

    async def broadcast(self, message: str):
        for conn in self.connections:
            await conn.send_text(message)

manager = ConnectionManager()

# --- WebSocket Chat Endpoint ---
@app.websocket("/ws/chat")
async def chat(websocket: WebSocket, username: str = "Guest"):
    await manager.connect(websocket)
    await manager.broadcast(f"{username} joined the chat!")
    try:
        while True:
            message = await websocket.receive_text()
            timestamp = datetime.now().strftime("%H:%M")
            await manager.broadcast(f"[{timestamp}] {username}: {message}")
    except WebSocketDisconnect:
        manager.disconnect(websocket)
        await manager.broadcast(f"{username} left the chat.")

# --- HTML Test Page for Chat ---
@app.get("/chat", response_class=HTMLResponse)
async def chat_page():
    return """
    <!DOCTYPE html>
    <html>
    <head><title>TechPath Chat</title>
    <style>
        body { font-family: Arial; max-width: 600px; margin: 40px auto; padding: 0 20px; }
        h2 { color: #2563eb; }
        #messages { border: 1px solid #ddd; padding: 10px; height: 300px; overflow-y: scroll; margin: 10px 0; border-radius: 8px; }
        .msg { padding: 4px 0; }
        .system { color: #888; font-style: italic; }
        input { padding: 8px; width: 70%; border: 1px solid #ddd; border-radius: 4px; }
        button { padding: 8px 16px; background: #2563eb; color: white; border: none; border-radius: 4px; cursor: pointer; }
    </style>
    </head>
    <body>
        <h2>TechPath Institute - Live Chat</h2>
        <p>Enter your name and start chatting!</p>
        <input id="name" placeholder="Your name (e.g., Rahul)" value="Rahul">
        <button onclick="connect()">Connect</button>
        <div id="messages"></div>
        <input id="msg" placeholder="Type a message..." onkeypress="if(event.key==='Enter')send()" disabled>
        <button onclick="send()" id="sendBtn" disabled>Send</button>

        <script>
        let ws;
        function connect() {
            const name = document.getElementById('name').value || 'Guest';
            ws = new WebSocket(`ws://localhost:8000/ws/chat?username=${name}`);
            ws.onmessage = (e) => {
                const div = document.getElementById('messages');
                const isSystem = e.data.includes('joined') || e.data.includes('left');
                div.innerHTML += `<div class="msg ${isSystem ? 'system' : ''}">${e.data}</div>`;
                div.scrollTop = div.scrollHeight;
            };
            ws.onopen = () => {
                document.getElementById('msg').disabled = false;
                document.getElementById('sendBtn').disabled = false;
                document.getElementById('name').disabled = true;
            };
            ws.onclose = () => {
                const div = document.getElementById('messages');
                div.innerHTML += '<div class="msg system">Disconnected.</div>';
            };
        }
        function send() {
            const input = document.getElementById('msg');
            if (input.value.trim()) {
                ws.send(input.value);
                input.value = '';
            }
        }
        </script>
    </body>
    </html>
    """
```

Test the WebSocket chat:

1. Make sure the server is running: `uvicorn auth_app:app --reload`
2. Open `http://localhost:8000/chat` in **two browser tabs**
3. In Tab 1: type name "Rahul" and click Connect
4. In Tab 2: type name "Priya" and click Connect
5. Send messages from both tabs — they should appear in both windows in real time

| Test | Expected |
|------|----------|
| Connect as Rahul | "Rahul joined the chat!" appears |
| Connect as Priya in another tab | "Priya joined the chat!" appears in both tabs |
| Send message from Rahul | Message appears in both tabs with timestamp |
| Close Priya's tab | "Priya left the chat." appears in Rahul's tab |

